 		list_del(&ptdesc->pt_list);
-		pagetable_free(ptdesc);
+
+		if (folio_test_pgtable(ptdesc_folio(ptdesc)))
+			pagetable_dtor_free(ptdesc);
+		else
+			pagetable_free(ptdesc);
 	}
 }
 
