+static void dump_cec_msg(struct it6625 *it6625, struct cec_msg *msg, char *str)
+{
+	int i;
+
+	dev_dbg(it6625->dev, "%s: from %d to %d len=%d", str,
+		msg->msg[0] >> 4, msg->msg[0] & 0x0f, msg->len);
+	for (i = 1; i < msg->len; i++)
+		dev_dbg(it6625->dev, " %02x", msg->msg[i]);
+}
