+static int it6625_mipi_reg_show(struct seq_file *s, void *data)
+{
+	struct it6625 *it6625 = s->private;
+	u8 reg_buf[256];
+
+	it6625_read_bytes(it6625, 0x00, reg_buf, sizeof(reg_buf));
+	it6625_regdump_print(s, reg_buf);
+
+	return 0;
+}
